<script setup>
import { ref, computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowUpRight, Aperture, ShieldCheck } from 'lucide-vue-next'
import { api, saveSession } from '../api'
const route=useRoute(),router=useRouter(), admin=computed(()=>route.path.startsWith('/admin')), register=ref(false), loading=ref(false),error=ref('')
const form=ref({username:'',password:'',name:''})
async function submit(){loading.value=true;error.value='';try{const data=await api(admin.value?'/auth/admin-login':register.value?'/auth/register':'/auth/login',{method:'POST',body:form.value,role:admin.value?'ADMIN':'USER'});saveSession(data);const redirect=String(route.query.redirect||'');router.replace(redirect.startsWith('/')&&!redirect.startsWith('//')?redirect:admin.value?'/admin':'/')}catch(e){error.value=e.message}finally{loading.value=false}}
</script>
<template><section class="auth-page wrap"><div class="auth-story"><Aperture :size="45"/><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h1>让灵感落地。<br>让创作发生。</h1><img src="/illustrations/camera.svg" alt="相机插画"><p>好装备，从光屿出发。</p></div><div class="auth-form"><span class="eyebrow">{{admin?'STAFF ACCESS':'WELCOME TO GEARHUB'}}</span><h2>{{admin?'登录门店工作台':register?'开启你的创作之旅':'欢迎回到光屿'}}</h2><p class="muted">{{admin?'使用现有员工账号登录，管理器材与预约。':'登录后即可预约器材、查看租赁进度。'}}</p><form @submit.prevent="submit"><label>账号<input v-model="form.username" required maxlength="32" autocomplete="username" :pattern="admin?undefined:'[a-zA-Z0-9_]{3,32}'" placeholder="输入账号"></label><label v-if="register&&!admin">姓名 / 昵称<input v-model="form.name" required maxlength="32" autocomplete="name" placeholder="我们该如何称呼你"></label><label>密码<input v-model="form.password" type="password" required :minlength="register?8:1" :autocomplete="register?'new-password':'current-password'" placeholder="输入密码"></label><p v-if="register" class="hint">账号为 3～32 位字母、数字或下划线；密码至少 8 个字符，最多 72 个 UTF-8 字节。</p><p v-if="error" class="alert error" role="alert">{{error}}</p><button class="button full" :disabled="loading">{{loading?'正在处理…':register&&!admin?'创建账号并登录':'登录'}}<ArrowUpRight :size="18"/></button></form><p v-if="!admin" class="auth-switch">{{register?'已经有账号？':'还没有账号？'}}<button class="text-button" @click="register=!register;error=''">{{register?'直接登录':'立即注册'}}</button></p><div class="auth-note"><ShieldCheck :size="17"/>预约后到店办理，平台不收取在线付款。</div></div></section></template>
